// handler: サーバー側に設定がなければ、誰も通さない
if (!deps.adminToken || req.token !== deps.adminToken) {
  return json(401, { error: 'unauthorized' });
}

// test: 設定がないときに、ヘッダーなしで通らないこと
const deps = { ...(await setup()), adminToken: undefined };
assert.equal((await handleOrderExport(deps, { token: undefined, query: october })).status, 401);

export interface OrderRepository {
  // 照合バッチ用。状態は必須のまま
  findByStatusUpdatedBefore(status: OrderStatus, before: Date): Promise<Order[]>;
  /** from 以上 to 未満に更新された注文（状態を問わない） */
  findUpdatedBetween(range: { from: Date; to: Date }): Promise<Order[]>;
}
